MemoryInstanceAsyncWaiter::MemoryInstanceAsyncWaiter(
    MemoryInstance* proxy) : proxy_(proxy) {}

MemoryInstanceAsyncWaiter::~MemoryInstanceAsyncWaiter() = default;

void MemoryInstanceAsyncWaiter::DropCaches(
    bool* out_result) {
  base::RunLoop loop;
  proxy_->DropCaches(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_result
,
             bool result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

bool MemoryInstanceAsyncWaiter::DropCaches(
    ) {
  bool async_wait_result;
  DropCaches(&async_wait_result);
  return async_wait_result;
}

void MemoryInstanceAsyncWaiter::Reclaim(
    ReclaimRequestPtr request, ReclaimResultPtr* out_result) {
  base::RunLoop loop;
  proxy_->Reclaim(std::move(request),
      base::BindOnce(
          [](base::RunLoop* loop,
             ReclaimResultPtr* out_result
,
             ReclaimResultPtr result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

ReclaimResultPtr MemoryInstanceAsyncWaiter::Reclaim(
    ReclaimRequestPtr request) {
  ReclaimResultPtr async_wait_result;
  Reclaim(std::move(request),&async_wait_result);
  return async_wait_result;
}






